mapper.select:
select t.*, u.name as leader_name, u.avatar as leader_avatar, a.title as activity_name, teacher.name as teacher_name, (select count(*) from team_member where team_id = t.id) as member_count from `team` t left join `user` u on t.leader_id = u.id left join `activity` a on t.activity_id = a.id left join `user` teacher on t.teacher_id = teacher.id
and t.team_name like concat('%', #{teamName}, '%') and t.status = #{status} and t.teacher_id = #{teacherId} and t.leader_id = #{leaderId} and t.activity_id = #{activityId} and t.competition_type = #{competitionType}
order by t.create_time desc

mapper.update:
update `team`
team_name = #{teamName}, description = #{description}, max_members = #{maxMembers}, leader_id = #{leaderId}, activity_id = #{activityId}, status = #{status}, member_count = #{memberCount}, create_time = #{createTime}, teacher_id = #{teacherId}, required_skills = #{requiredSkills}, competition_type = #{competitionType},
where id = #{id}
